files.content:
/* Sponsor. Every value comes from a token; nothing here is a literal colour.
 *
 * BDS-043: the slot is never re-coloured. So this file sets the label's type
 * and the logo's size box, and it sets nothing at all inside the logo: no
 * background, no fill, no filter, no border. The plate the drawing shows is
 * part of the sponsor's own asset until a decision says otherwise, because a
 * plate colour written here would be a colour the library invented for a brand
 * it does not own. */

.gs-sponsor {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
}

/* The line that says this is a sponsor. Quieter than the game and never
   absent: a logo with nothing above it is an advert nobody was told about. */
.gs-sponsor__label {
  flex: none;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink-secondary);
}

/* The size box, and nothing else.
 *
 * The five heights are literal pixels rather than tokens on purpose. A token is
 * a theme axis, and BDS-043 says this slot is not on any theme axis: the arcade
 * theme must not make a sponsor's mark larger than the stadium theme does. They
 * are the sizes specimen 4g draws, and they change when the drawing changes. */
.gs-sponsor__logo {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
}

.gs-sponsor__logo > * {
  display: block;
  width: auto;
  height: 100%;
  max-width: 100%;
}

.gs-sponsor--inline .gs-sponsor__logo { height: 28px; }
.gs-sponsor--hud .gs-sponsor__logo { height: 32px; }
.gs-sponsor--reward .gs-sponsor__logo { height: 22px; }
.gs-sponsor--interstitial .gs-sponsor__logo { height: 56px; }
.gs-sponsor--badge .gs-sponsor__logo { height: 16px; }

/* The interstitial is the one lockup that owns its whole surface, so it stacks
   and centres. Everything else sits in a row beside the thing it belongs to. */
.gs-sponsor--interstitial {
  flex-direction: column;
  justify-content: center;
  gap: var(--gs-space-3);
  padding: var(--gs-space-6) var(--gs-space-4);
  text-align: center;
}

.gs-sponsor--reward { align-items: flex-start; }

.gs-sponsor__name {
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  color: var(--gs-color-ink);
}

/* Present in the accessible name, not on screen, when the logo carries the
   brand visually. */
.gs-sponsor__name--hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  white-space: nowrap;
  clip-path: inset(50%);
  border: 0;
}
